static void tohex(const uint8_t *b, char *o) { for (int i = 0; i < 32; i++) sprintf(o + 2 * i, "%02x", b[i]); }
/* The expected output is compared through its SHA-256 so long outputs stay short in the table. */
int main(void) {
    int n = (int)(sizeof C / sizeof *C);
    for (int k = 0; k < n; k++) {
        size_t len = C[k].len;
        uint8_t *buf = malloc(len + 16);
        memset(buf, 0xEE, len + 16);
        int rc = hkdf_sha256(C[k].s, C[k].sl, C[k].i, C[k].il, C[k].n, C[k].nl, buf, len);
        Sha256 sh; uint8_t d[32]; char hex[80];
        sha256_init(&sh); sha256_update(&sh, buf, len); sha256_final(&sh, d); tohex(d, hex);
        int guard = 1; for (size_t j = len; j < len + 16; j++) if (buf[j] != 0xEE) guard = 0;
        char name[96];
        snprintf(name, sizeof name, "case %d (salt %zu, ikm %zu, info %zu, output %zu bytes)", k, C[k].sl, C[k].il, C[k].nl, len);
        CHECK(name, rc == 0 && strcmp(hex, C[k].sha) == 0, "returned %d; output digest %s, expected %s", rc, hex, C[k].sha);
        CHECK("writes no more than the requested length", guard, "case %d wrote past %zu bytes", k, len);
        free(buf);
    }
    {
        uint8_t big[8200]; memset(big, 0xEE, sizeof big);
        int rc = hkdf_sha256(C[5].s, C[5].sl, C[5].i, C[5].il, C[5].n, C[5].nl, big, 255 * 32 + 1);
        int clean = 1; for (size_t j = 0; j < sizeof big; j++) if (big[j] != 0xEE) clean = 0;
        CHECK("asking for more than 255 blocks fails and writes nothing", rc == -1 && clean, "must return -1 for a length over 8160 and leave the buffer alone");
    }
    return 0;
}
